from __future__ import annotations

import asyncio
import dataclasses
from typing import Any

import pytest

import llm_router
import tests.llm_router.support.builders as builders

pytestmark = pytest.mark.verification_kind("unit")


@dataclasses.dataclass
class _MockKey:
    key_id: str = "test-key-id"


@dataclasses.dataclass
class _MockRequest:
    key: _MockKey = dataclasses.field(default_factory=_MockKey)
    route: Any = None


@dataclasses.dataclass
class _MockResult:
    traces: list[Any] = dataclasses.field(default_factory=list)
    final_trace: Any = None
    response: Any = None
    content: Any = None
    request_id: str = ""


def _create_runtime() -> Any:
    router_cls = getattr(llm_router, "RouterRuntime", None)
    if router_cls is None:
        try:
            import llm_router._internal.runtime.router as router_mod

            router_cls = getattr(router_mod, "RouterRuntime", None)
        except Exception:
            internal = getattr(llm_router, "_internal", None)
            runtime_pkg = getattr(internal, "runtime", None)
            router_mod = getattr(runtime_pkg, "router", None)
            router_cls = getattr(router_mod, "RouterRuntime", None)

    spec = "openai/gpt-4o,anthropic/claude-3-5-sonnet"
    if router_cls is not None:
        try:
            return router_cls(spec=spec)
        except Exception:
            pass

    if hasattr(builders, "build_runtime"):
        try:
            return builders.build_runtime(spec=spec)
        except Exception:
            try:
                return builders.build_runtime()
            except Exception:
                pass

    if hasattr(builders, "build_router"):
        try:
            r = builders.build_router(spec=spec)
            for attr in ("_runtime", "runtime", "_impl", "_router"):
                if hasattr(r, attr):
                    return getattr(r, attr)
            return r
        except Exception:
            pass

    if hasattr(llm_router, "LLMRouter"):
        r = llm_router.LLMRouter(spec=spec)
        for attr in ("_runtime", "runtime", "_impl", "_router"):
            if hasattr(r, attr):
                return getattr(r, attr)
        return r

    msg = "Unable to instantiate a RouterRuntime instance"
    raise RuntimeError(msg)


def _setup_routing(runtime: Any, first_route: Any, second_route: Any) -> None:
    def fake_prepare_request(*args: Any, **kwargs: Any) -> tuple[Any, int]:
        route = (
            kwargs.get("route")
            if "route" in kwargs
            else (args[1] if len(args) > 1 else None)
        )
        if route == first_route:
            msg = f"Simulated failure for route: {route}"
            raise RuntimeError(msg)
        req = _MockRequest(key=_MockKey(key_id="test-key-id"), route=route)
        return req, 0

    runtime._prepare_request = fake_prepare_request

    async def fake_call_async(*args: Any, **kwargs: Any) -> Any:
        return "fake-response"

    def fake_call_sync(*args: Any, **kwargs: Any) -> Any:
        return "fake-response"

    runtime._call_async_with_timeout = fake_call_async
    runtime._call_sync_with_timeout = fake_call_sync

    for name in getattr(runtime._run_async, "__code__", ()).co_names:
        if "call" in name or "exec" in name:
            setattr(runtime, name, fake_call_async)
    for name in getattr(runtime._run_sync, "__code__", ()).co_names:
        if "call" in name or "exec" in name:
            setattr(runtime, name, fake_call_sync)

    executor = getattr(runtime, "_executor", None)
    if executor is not None:
        for name in ("execute", "call", "execute_sync", "call_sync"):
            setattr(executor, name, fake_call_sync)
        for name in ("execute_async", "call_async"):
            setattr(executor, name, fake_call_async)

    runtime._record_success = lambda *args, **kwargs: None
    runtime._record_failure = lambda *args, **kwargs: None
    runtime._log_attempt_started = lambda *args, **kwargs: None
    runtime._log_attempt_succeeded = lambda *args, **kwargs: None
    runtime._log_attempt_failed = lambda *args, **kwargs: None
    runtime._log_route_selected = lambda *args, **kwargs: None
    runtime._log_route_blocked = lambda *args, **kwargs: None
    runtime._log_request_started = lambda *args, **kwargs: None
    runtime._log_request_failed = lambda *args, **kwargs: None

    def fake_complete_success(*args: Any, **kwargs: Any) -> Any:
        traces = kwargs.get("traces", [])
        final_trace = kwargs.get("final_trace", None)
        response = kwargs.get("response", None)
        content = kwargs.get("content", None)
        request_id = kwargs.get("request_id", "")
        return _MockResult(
            traces=list(traces) if traces else [],
            final_trace=final_trace,
            response=response,
            content=content,
            request_id=request_id,
        )

    runtime._complete_success = fake_complete_success


@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
def test_async_fallback_success_remembered_matches_sync() -> None:
    async def _run_test() -> None:
        runtime_async = _create_runtime()
        routes = list(runtime_async.route_plan)
        assert len(routes) >= 2, "Test requires at least two routes"
        first_route = routes[0]
        second_route = routes[1]

        _setup_routing(runtime_async, first_route, second_route)

        res_async_1 = await runtime_async._run_async(
            content="test prompt",
            call_overrides={"round_robin_start": False},
        )
        assert res_async_1.final_trace.route == second_route
        assert len(res_async_1.traces) == 1
        assert res_async_1.traces[0].route == first_route

        assert runtime_async._sticky_start_route_index is not None, (
            "Expected fallback success to be remembered in _sticky_start_route_index"
        )
        assert runtime_async._sticky_start_route_index == 1

        res_async_2 = await runtime_async._run_async(
            content="test prompt",
            call_overrides={"round_robin_start": False},
        )
        assert res_async_2.final_trace.route == second_route
        assert len(res_async_2.traces) == 0, (
            f"Expected next async request to start on fallback route with 0 failed traces, "
            f"got {len(res_async_2.traces)}"
        )

        runtime_sync = _create_runtime()
        _setup_routing(runtime_sync, first_route, second_route)

        res_sync_1 = runtime_sync._run_sync(
            content="test prompt",
            call_overrides={"round_robin_start": False},
        )
        assert res_sync_1.final_trace.route == second_route
        assert len(res_sync_1.traces) == 1

        res_sync_2 = runtime_sync._run_sync(
            content="test prompt",
            call_overrides={"round_robin_start": False},
        )
        assert res_sync_2.final_trace.route == second_route
        assert len(res_sync_2.traces) == 0

        assert len(res_async_2.traces) == len(res_sync_2.traces)
        assert [t.route for t in res_async_2.traces] == [
            t.route for t in res_sync_2.traces
        ]
        assert res_async_2.final_trace.route == res_sync_2.final_trace.route

    asyncio.run(_run_test())
